-- wasmcraft: a WebAssembly interpreter in pure Lua, amalgamated for CC:Tweaked.
-- Generated by tools/amalgamate. Run as a program:  wasmcraft <module.wasm> [args]
local preload, loaded = {}, {}
local function require(name)
  if loaded[name] ~= nil then return loaded[name] end
  local f = preload[name]; if not f then error('module not bundled: '..name) end
  local m = f(name); if m == nil then m = true end; loaded[name] = m; return m
end
