  [0x90] = "f32.nearest", [0x91] = "f32.sqrt", [0x92] = "f32.add", [0x93] = "f32.sub", [0x94] = "f32.mul",
  [0x95] = "f32.div", [0x96] = "f32.min", [0x97] = "f32.max", [0x98] = "f32.copysign",
  -- f64 arithmetic
  [0x99] = "f64.abs", [0x9a] = "f64.neg", [0x9b] = "f64.ceil", [0x9c] = "f64.floor", [0x9d] = "f64.trunc",
  [0x9e] = "f64.nearest", [0x9f] = "f64.sqrt", [0xa0] = "f64.add", [0xa1] = "f64.sub", [0xa2] = "f64.mul",
  [0xa3] = "f64.div", [0xa4] = "f64.min", [0xa5] = "f64.max", [0xa6] = "f64.copysign",
  -- conversions
  [0xa7] = "i32.wrap_i64",
  [0xa8] = "i32.trunc_f32_s", [0xa9] = "i32.trunc_f32_u", [0xaa] = "i32.trunc_f64_s", [0xab] = "i32.trunc_f64_u",
  [0xac] = "i64.extend_i32_s", [0xad] = "i64.extend_i32_u",
  [0xae] = "i64.trunc_f32_s", [0xaf] = "i64.trunc_f32_u", [0xb0] = "i64.trunc_f64_s", [0xb1] = "i64.trunc_f64_u",
  [0xb2] = "f32.convert_i32_s", [0xb3] = "f32.convert_i32_u", [0xb4] = "f32.convert_i64_s", [0xb5] = "f32.convert_i64_u",
  [0xb6] = "f32.demote_f64",
  [0xb7] = "f64.convert_i32_s", [0xb8] = "f64.convert_i32_u", [0xb9] = "f64.convert_i64_s", [0xba] = "f64.convert_i64_u",
  [0xbb] = "f64.promote_f32",
  [0xbc] = "i32.reinterpret_f32", [0xbd] = "i64.reinterpret_f64",
  [0xbe] = "f32.reinterpret_i32", [0xbf] = "f64.reinterpret_i64",
  -- sign extension
  [0xc0] = "i32.extend8_s", [0xc1] = "i32.extend16_s",
  [0xc2] = "i64.extend8_s", [0xc3] = "i64.extend16_s", [0xc4] = "i64.extend32_s",
}
for code, name in pairs(NULLARY) do OPS[code] = simple(name) end

-- reference types
OPS[0xd0] = function(r) valtype(r); return { op = "ref.null" } end
OPS[0xd1] = simple("ref.is_null")
OPS[0xd2] = lebop("ref.func", "func")

-- 0xfc prefix: bulk memory + saturating truncation
local FC = {
  [0] = "i32.trunc_sat_f32_s", [1] = "i32.trunc_sat_f32_u",
  [2] = "i32.trunc_sat_f64_s", [3] = "i32.trunc_sat_f64_u",
  [4] = "i64.trunc_sat_f32_s", [5] = "i64.trunc_sat_f32_u",
  [6] = "i64.trunc_sat_f64_s", [7] = "i64.trunc_sat_f64_u",
}
OPS[0xfc] = function(r)
  local sub = r:u_leb()
  local name = FC[sub]
  if name then return { op = name } end
  if sub == 8 then local d = r:u_leb(); r:byte(); return { op = "memory.init", data = d } end
  if sub == 9 then return { op = "data.drop", data = r:u_leb() } end
  if sub == 10 then r:byte(); r:byte(); return { op = "memory.copy" } end
  if sub == 11 then r:byte(); return { op = "memory.fill" } end
  if sub == 12 then local e = r:u_leb(); local t = r:u_leb(); return { op = "table.init", elem = e, table = t } end
  if sub == 13 then return { op = "elem.drop", elem = r:u_leb() } end
  if sub == 14 then local a = r:u_leb(); local b = r:u_leb(); return { op = "table.copy", dst = a, src = b } end
  if sub == 15 then return { op = "table.grow", table = r:u_leb() } end
  if sub == 16 then return { op = "table.size", table = r:u_leb() } end
  if sub == 17 then return { op = "table.fill", table = r:u_leb() } end
  error("unimplemented 0xfc subop " .. sub)
end

-- i64.const needs an i64 value; decode raw little-endian via signed LEB into {h,l}.
-- We import int64 lazily to avoid a cycle at module load.
local int64
OPS[0x42] = function(r)
  int64 = int64 or require("int64")
  return { op = "i64.const", v = int64.read_sleb(r) }
end

-- Decode an expression body into a flat instruction list, linking block/loop/if
-- to their matching else/end so branches resolve in O(1).
local function decodeBody(r)
  local instrs = {}
  local depth = 0
  while true do
    local op = r:byte()
    if op == 0x0b then -- end
      if depth == 0 then break end
      depth = depth - 1
      instrs[#instrs + 1] = { op = "end" }
    else
      local f = OPS[op]
      if not f then error(string.format("unimplemented opcode 0x%02x at byte %d", op, r.pos - 1)) end
      local ins = f(r)
      if ins.op == "block" or ins.op == "loop" or ins.op == "if" then depth = depth + 1 end
      instrs[#instrs + 1] = ins
    end
  end
  -- link control structures
  local stack = {}
  for i = 1, #instrs do
    local o = instrs[i].op
    if o == "block" or o == "loop" or o == "if" then
      stack[#stack + 1] = i
    elseif o == "else" then
      instrs[stack[#stack]].else_pc = i
      instrs[i].opener = stack[#stack]
    elseif o == "end" then
      local j = stack[#stack]; stack[#stack] = nil
      instrs[j].end_pc = i
      instrs[i].opener = j
    end
  end
  -- resolve else markers' end_pc (jump target when then-branch falls through)
  for i = 1, #instrs do
    if instrs[i].op == "else" then
      instrs[i].end_pc = instrs[instrs[i].opener].end_pc
    end
  end
  return instrs
end
M.decodeBody = decodeBody

-- A constant expression (used by globals/elem/data offsets): same decoder.
local function decodeConstExpr(r) return decodeBody(r) end

-- ---- sections ------------------------------------------------------------

local function decodeTypes(r)
  return vec(r, function(rr)
    local form = rr:byte()
    if form ~= 0x60 then error(string.format("expected functype 0x60, got 0x%02x", form)) end
    return { params = vec(rr, valtype), results = vec(rr, valtype) }
  end)
end

local function limits(r)
  local flag = r:byte()
  local min = r:u_leb()
  local max = nil
  if flag == 1 then max = r:u_leb() end
  return min, max
end

local function decodeImports(r, mod)
  return vec(r, function(rr)
    local mlen = rr:u_leb(); local module = rr:bytes(mlen)
    local nlen = rr:u_leb(); local name = rr:bytes(nlen)
    local kind = rr:byte()
    local imp = { module = module, name = name }
    if kind == 0 then
      imp.kind = "func"; imp.typeidx = rr:u_leb(); mod.numImportedFuncs = mod.numImportedFuncs + 1
      mod.importedFuncs[#mod.importedFuncs + 1] = imp
    elseif kind == 1 then
      imp.kind = "table"; local et = valtype(rr); local mn, mx = limits(rr); imp.min = mn; imp.max = mx
    elseif kind == 2 then
      imp.kind = "mem"; local mn, mx = limits(rr); imp.min = mn; imp.max = mx; mod.importedMem = imp
    elseif kind == 3 then
      imp.kind = "global"; imp.valtype = valtype(rr); imp.mut = rr:byte(); mod.numImportedGlobals = mod.numImportedGlobals + 1
    else error("bad import kind " .. kind) end
    return imp
  end)
end

local function decodeFunctions(r) return vec(r, function(rr) return rr:u_leb() end) end

local function decodeTables(r)
  return vec(r, function(rr)
    local et = valtype(rr)
    local mn, mx = limits(rr)
    return { elemtype = et, min = mn, max = mx }
  end)
end

local function decodeMemories(r)
  return vec(r, function(rr)
    local mn, mx = limits(rr)
    return { min = mn, max = mx }
  end)
end

local function decodeGlobals(r)
  return vec(r, function(rr)
    local vt = valtype(rr)
    local mut = rr:byte()
    local init = decodeConstExpr(rr)
    return { valtype = vt, mut = mut, init = init }
  end)
end

local EXPORT_KIND = { [0] = "func", [1] = "table", [2] = "mem", [3] = "global" }
local function decodeExports(r)
  local out = {}
  local n = r:u_leb()
  for _ = 1, n do
    local nameLen = r:u_leb()
    local name = r:bytes(nameLen)
    local kind = EXPORT_KIND[r:byte()]
    out[name] = { kind = kind, index = r:u_leb() }
  end
  return out
end

local function decodeElements(r)
  return vec(r, function(rr)
    local flag = rr:u_leb()
    -- Support the common encodings emitted by LLVM/wabt.
    if flag == 0 then
      -- active, table 0, offset expr, vec funcidx
      local offset = decodeConstExpr(rr)
      local funcs = vec(rr, function(x) return x:u_leb() end)
      return { mode = "active", table = 0, offset = offset, funcs = funcs }
    elseif flag == 1 then
      rr:byte() -- elemkind (0 = funcref)
      local funcs = vec(rr, function(x) return x:u_leb() end)
      return { mode = "passive", funcs = funcs }
    elseif flag == 2 then
      local tbl = rr:u_leb()
      local offset = decodeConstExpr(rr)
      rr:byte() -- elemkind
      local funcs = vec(rr, function(x) return x:u_leb() end)
      return { mode = "active", table = tbl, offset = offset, funcs = funcs }
    elseif flag == 3 then
      rr:byte()
      local funcs = vec(rr, function(x) return x:u_leb() end)
      return { mode = "declarative", funcs = funcs }
    else
      error("unsupported elem segment flag " .. flag)
    end
  end)
end

local function decodeData(r)
  return vec(r, function(rr)
    local flag = rr:u_leb()
    if flag == 0 then
      local offset = decodeConstExpr(rr)
      local len = rr:u_leb()
      return { mode = "active", memory = 0, offset = offset, bytes = rr:bytes(len) }
    elseif flag == 1 then
      local len = rr:u_leb()
      return { mode = "passive", bytes = rr:bytes(len) }
    elseif flag == 2 then
      local mem = rr:u_leb()
      local offset = decodeConstExpr(rr)
      local len = rr:u_leb()
      return { mode = "active", memory = mem, offset = offset, bytes = rr:bytes(len) }
    else
      error("unsupported data segment flag " .. flag)
    end
  end)
end

-- ---- top-level -----------------------------------------------------------

local function decodeCodeSection(r)
  return vec(r, function(rr)
    local size = rr:u_leb()
    local endPos = rr.pos + size
    local locals = {}
    local nDecl = rr:u_leb()
    for _ = 1, nDecl do
      local count = rr:u_leb()
      local t = valtype(rr)
      for _ = 1, count do locals[#locals + 1] = t end
    end
    local body = decodeBody(rr)
    rr.pos = endPos
    return { locals = locals, body = body }
  end)
end

function M.load(bytes)
  local r = Reader.new(bytes)
  if r:bytes(4) ~= "\0asm" then error("bad magic: not a wasm module") end
  local version = r:u32()
  if version ~= 1 then error("unsupported wasm version " .. version) end

  local mod = {
    types = {}, imports = {}, importedFuncs = {}, importedMem = nil,
    numImportedFuncs = 0, numImportedGlobals = 0,
    funcTypeIdx = {}, tables = {}, memories = {}, globals = {},
    exports = {}, elements = {}, datas = {}, codes = {}, start = nil,
  }

  while not r:eof() do
    local id = r:byte()
    local len = r:u_leb()
    local secEnd = r.pos + len
    if id == 1 then mod.types = decodeTypes(r)
    elseif id == 2 then mod.imports = decodeImports(r, mod)
    elseif id == 3 then mod.funcTypeIdx = decodeFunctions(r)
    elseif id == 4 then mod.tables = decodeTables(r)
    elseif id == 5 then mod.memories = decodeMemories(r)
    elseif id == 6 then mod.globals = decodeGlobals(r)
    elseif id == 7 then mod.exports = decodeExports(r)
    elseif id == 8 then mod.start = r:u_leb()
    elseif id == 9 then mod.elements = decodeElements(r)
    elseif id == 10 then mod.codes = decodeCodeSection(r)
    elseif id == 11 then mod.datas = decodeData(r)
    else
      -- custom(0), datacount(12), and anything else: skip by length
    end
    r.pos = secEnd
  end

  return mod
end

return M
end
preload['wasi'] = function(...)
-- Minimal WASI preview1 host. Two tiers:
--   * stdout/clock/args/etc. — enough to boot a wasi-libc "command" module.
--   * a real filesystem (preopened dir + path_open/fd_read/fd_write/fd_seek/
--     filestat/unlink/...) backed by host files, so SQLite persists an on-disk
--     .db through WASI. Each fd keeps an in-memory image (random read/write/seek);
--     the host file is read whole on open and written whole on sync/close, which
--     is all CC's fs API supports.
local spack, sunpack = string.pack, string.unpack
local schar = string.char
local floor = math.floor

local M = {}
M.EXIT = {} -- unique marker table for proc_exit unwinding

-- ---- little-endian struct writers/readers over linear memory --------------
local function ru32(mem, a) return (sunpack("<I4", mem:loadstr(a, 4))) end
local function wu32(mem, a, v) mem:storestr(a, spack("<I4", v % 4294967296)) end
local function wu64(mem, a, v)
  v = floor(v)
  mem:storestr(a, spack("<I4", v % 4294967296))
  mem:storestr(a + 4, spack("<I4", floor(v / 4294967296) % 4294967296))
end
local function i64num(v) -- interpreter passes i64 as {h,l}
  if type(v) == "table" then
    local n = v.h * 4294967296 + v.l
    if v.h >= 0x80000000 then n = n - 2 ^ 64 end
    return n
  end
  return v
end
local function hasflag(x, f) return floor(x / f) % 2 == 1 end

-- ---- in-memory file image (random access; flushed whole) ------------------
local FileImage = {}
FileImage.__index = FileImage

local function bytes_to_string(b, from, to) -- [from,to) 0-indexed
  local parts, chunk, ci = {}, {}, 0
  for i = from, to - 1 do
    ci = ci + 1; chunk[ci] = b[i] or 0
    if ci == 4096 then parts[#parts + 1] = schar((table.unpack or unpack)(chunk)); ci = 0; chunk = {} end
  end
  if ci > 0 then
    local last = {}
    for k = 1, ci do last[k] = chunk[k] end
    parts[#parts + 1] = schar((table.unpack or unpack)(last))
  end
  return table.concat(parts)
end

function FileImage.new(s)
  local o = setmetatable({ b = {}, len = 0, dirty = false }, FileImage)
  if s and #s > 0 then o:write(0, s) end
  o.dirty = false
  return o
end
function FileImage:read(pos, n)
  local e = pos + n; if e > self.len then e = self.len end
  if e <= pos then return "" end
  return bytes_to_string(self.b, pos, e)
end
function FileImage:write(pos, s)
  local b = self.b
  for i = 1, #s do b[pos + i - 1] = string.byte(s, i) end
  local nend = pos + #s
  if nend > self.len then self.len = nend end
  self.dirty = true
end
function FileImage:truncate(n)
  if n < self.len then for i = n, self.len - 1 do self.b[i] = nil end end
  self.len = n; self.dirty = true
end
function FileImage:tostring() return bytes_to_string(self.b, 0, self.len) end

-- ---- default host filesystem backends ------------------------------------
-- A host fs is: { read(path)->str|nil, write(path,data), exists(path)->bool,
--                 unlink(path), size(path)->n|nil, mkdir(path) }
local function io_hostfs(root)
  root = root or "."
  local function full(p)
    if p:sub(1, 1) == "/" then return p end
    if p:sub(1, 2) == "./" then p = p:sub(3) end
    return root .. "/" .. p
  end
  return {
    read = function(p) local f = io.open(full(p), "rb"); if not f then return nil end local d = f:read("*a"); f:close(); return d end,
    write = function(p, d) local f = assert(io.open(full(p), "wb")); f:write(d); f:close() end,
    exists = function(p) local f = io.open(full(p), "rb"); if f then f:close(); return true end return false end,
    size = function(p) local f = io.open(full(p), "rb"); if not f then return nil end local n = f:seek("end"); f:close(); return n end,
    unlink = function(p) os.remove(full(p)) end,
    mkdir = function() end,
  }
end
M.io_hostfs = io_hostfs

-- ---- WASI errnos / constants ---------------------------------------------
local E = { SUCCESS = 0, BADF = 8, EXIST = 20, INVAL = 28, ISDIR = 31, NOENT = 44, NOSYS = 52, NOTDIR = 54 }
local FT = { unknown = 0, chardev = 2, dir = 3, file = 4 }

-- opts: { write, writeerr, args, env, fs = <hostfs>, root = "." }
function M.make(opts)
  opts = opts or {}
  local write = opts.write or io.write
  local writeerr = opts.writeerr or write
  local argv = opts.args or {}
  local hostfs = opts.fs
  if hostfs == nil and opts.root then hostfs = io_hostfs(opts.root) end

  local W = {}

  -- file descriptor table (0/1/2 std; 3 = preopened ".")
  local fds = {
    [0] = { kind = "stdin", reader = opts.stdin }, [1] = { kind = "stdout" }, [2] = { kind = "stderr" },
  }
  if hostfs then fds[3] = { kind = "dir", name = "/" } end
  local next_fd = 4
  local PRENAME = "/" -- preopen the root; SQLite absolutizes paths via getcwd
  -- name -> entry, so path-based stat/unlink see files that are open (and only
  -- flushed to disk on sync/close) and directories created for dotfile locking.
  local byname = {}

  local function resolve(path) return path end -- wasi-libc already stripped the preopen prefix

  -- ---- streams + non-fs basics -------------------------------------------
  W.fd_write = function(a, inst)
    local mem = inst.memory
    local fd, iovs, iovs_len, nwritten = a[1], a[2], a[3], a[4]
    local parts, total = {}, 0
    for k = 0, iovs_len - 1 do
      local base = iovs + k * 8
      local ptr = ru32(mem, base); local len = ru32(mem, base + 4)
      parts[#parts + 1] = mem:loadstr(ptr, len); total = total + len
    end
    local s = table.concat(parts)
    local e = fds[fd]
    if e and e.kind == "file" then
      if e.append then e.pos = e.img.len end
      e.img:write(e.pos, s); e.pos = e.pos + #s
    elseif fd == 2 then writeerr(s) else write(s) end
    wu32(mem, nwritten, total)
    return { 0 }
  end

  W.fd_read = function(a, inst)
    local mem = inst.memory
    local fd, iovs, iovs_len, nread = a[1], a[2], a[3], a[4]
    local e = fds[fd]
    local total = 0
    if e and e.kind == "file" then
      for k = 0, iovs_len - 1 do
        local base = iovs + k * 8
        local ptr = ru32(mem, base); local len = ru32(mem, base + 4)
        local chunk = e.img:read(e.pos, len)
        mem:storestr(ptr, chunk); e.pos = e.pos + #chunk; total = total + #chunk
        if #chunk < len then break end
      end
    elseif e and e.kind == "stdin" and e.reader then
      -- stdin from a host reader: reader(maxlen) -> string ("" = EOF). May yield
      -- (when driven inside a coroutine) to wait for the next line of input.
      for k = 0, iovs_len - 1 do
        local base = iovs + k * 8
        local ptr = ru32(mem, base); local len = ru32(mem, base + 4)
        local chunk = e.reader(len) or ""
        mem:storestr(ptr, chunk); total = total + #chunk
        if #chunk < len then break end
      end
    end
    wu32(mem, nread, total)
    return { 0 }
  end

  local function flush(e)
    if e.kind == "file" and e.img.dirty and hostfs then
      hostfs.write(e.hostpath, e.img:tostring()); e.img.dirty = false
    end
  end

  W.fd_close = function(a)
    local e = fds[a[1]]
    if e then flush(e); fds[a[1]] = nil; if e.hostpath then byname[e.hostpath] = nil end end
    return { 0 }
  end
  W.fd_sync = function(a) local e = fds[a[1]]; if e then flush(e) end return { 0 } end
  W.fd_datasync = W.fd_sync

  W.fd_seek = function(a, inst)
    local fd, off, whence, outp = a[1], i64num(a[2]), a[3], a[4]
    local e = fds[fd]
    if not e then return { E.BADF } end
    if e.kind == "file" then
      local base = (whence == 0 and 0) or (whence == 1 and e.pos) or e.img.len
      e.pos = base + off
      wu64(inst.memory, outp, e.pos)
      return { 0 }
    end
    wu64(inst.memory, outp, 0)
    return { 0 }
  end

  W.fd_fdstat_get = function(a, inst)
    local mem, fd, buf = inst.memory, a[1], a[2]
    for i = 0, 23 do mem:set8(buf + i, 0) end
    local e = fds[fd]
    local ft = FT.chardev
    if e then
      if e.kind == "file" then ft = FT.file elseif e.kind == "dir" then ft = FT.dir end
    end
    mem:set8(buf, ft)
    -- grant all rights so libc permits every op, EXCEPT: for a character device
    -- (the std streams) clear FD_SEEK(0x4)+FD_TELL(0x20) so wasi-libc's isatty()
    -- returns true -> programs (Picat's REPL) treat the stream as a terminal.
    local base = 0xFFFFFFFF
    if ft == FT.chardev then base = 0xFFFFFFDB end
    mem:storestr(buf + 8, spack("<I4", base) .. spack("<I4", 0xFFFFFFFF))
    mem:storestr(buf + 16, spack("<I4", 0xFFFFFFFF) .. spack("<I4", 0xFFFFFFFF))
    return { 0 }
  end
  W.fd_fdstat_set_flags = function(a) local e = fds[a[1]]; if e then e.append = hasflag(a[2], 1) end return { 0 } end

  local function write_filestat(mem, buf, filetype, size)
    for i = 0, 63 do mem:set8(buf + i, 0) end
    mem:set8(buf + 16, filetype)   -- filetype
    mem:storestr(buf + 24, spack("<I4", 1) .. spack("<I4", 0)) -- nlink = 1
    wu64(mem, buf + 32, size)      -- size
  end

  W.fd_filestat_get = function(a, inst)
    local e = fds[a[1]]
    if not e then return { E.BADF } end
    local ft = (e.kind == "file" and FT.file) or (e.kind == "dir" and FT.dir) or FT.chardev
    write_filestat(inst.memory, a[2], ft, e.img and e.img.len or 0)
    return { 0 }
  end
  W.fd_filestat_set_size = function(a)
    local e = fds[a[1]]; if not (e and e.img) then return { E.BADF } end
    e.img:truncate(i64num(a[2]))
    return { 0 }
  end

  W.fd_prestat_get = function(a, inst)
    if a[1] == 3 and hostfs then
      local mem, buf = inst.memory, a[2]
      mem:set8(buf, 0)               -- tag = dir
      wu32(mem, buf + 4, #PRENAME)   -- name length
      return { 0 }
    end
    return { E.BADF }
